<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Brand,ProductCategory,Industry,Application};use Illuminate\Http\Request;use Illuminate\Support\Str;
class SimpleCatalogController extends Controller {
 private function map(string $type){return match($type){'brands'=>[Brand::class,'admin.brands','Brand'],'categories'=>[ProductCategory::class,'admin.categories','Category'],'industries'=>[Industry::class,'admin.industries','Industry'],'applications'=>[Application::class,'admin.applications','Application'],default=>abort(404)};}
 public function index(Request $r,string $type){[$m,$view,$label]=$this->map($type);$items=$m::query()->when($r->q,fn($q)=>$q->where('name','like','%'.$r->q.'%'))->orderBy('name')->paginate(30);return view($view.'.index',compact('items','type','label'));}
 public function create(string $type){[$m,$view,$label]=$this->map($type);$item=new $m;return view($view.'.form',compact('item','type','label'));}
 public function store(Request $r,string $type){[$m]=$this->map($type);$d=$this->validateData($r,$type);$m::create($d);return redirect()->route('admin.catalog.index',$type)->with('success','Created successfully.');}
 public function edit(string $type,int $id){[$m,$view,$label]=$this->map($type);$item=$m::findOrFail($id);return view($view.'.form',compact('item','type','label'));}
 public function update(Request $r,string $type,int $id){[$m]=$this->map($type);$item=$m::findOrFail($id);$item->update($this->validateData($r,$type,$id));return back()->with('success','Updated successfully.');}
 public function destroy(string $type,int $id){[$m]=$this->map($type);$m::findOrFail($id)->delete();return back()->with('success','Deleted successfully.');}
 private function validateData(Request $r,string $type,?int $id=null):array{$table=match($type){'brands'=>'brands','categories'=>'product_categories','industries'=>'industries','applications'=>'applications'};$d=$r->validate(['name'=>'required|max:255','slug'=>'nullable|max:255|unique:'.$table.',slug,'.($id??'NULL'),'description'=>'nullable','short_description'=>'nullable|max:2000','country'=>'nullable|max:150','website'=>'nullable|url|max:255','parent_id'=>'nullable|integer','featured'=>'nullable|boolean','status'=>'nullable|boolean']);$d['slug']=$d['slug']?:Str::slug($d['name']);$d['status']=$r->boolean('status');if(in_array($type,['brands','categories','industries']))$d['featured']=$r->boolean('featured');return $d;}}
